from httpbin.core import app
client = app.test_client()

def test_post_form_data_returns_200_with_all_keys():
    r = client.post('/post', data={'mykey': 'myvalue'},
                    content_type='application/x-www-form-urlencoded')
    assert r.status_code == 200
    assert 'application/json' in r.content_type
    body = r.get_json()
    expected_keys = {'url', 'args', 'headers', 'form', 'data', 'files', 'json', 'origin'}
    assert set(body.keys()) == expected_keys
    assert body['form'] == {'mykey': 'myvalue'}
    assert body['data'] == ''
    assert body['json'] is None
    assert body['args'] == {}
    assert body['files'] == {}

test_post_form_data_returns_200_with_all_keys()

import json as _json
from httpbin.core import app
client = app.test_client()

def test_post_json_body_reflected_in_json_field():
    payload = {'alpha': 1, 'beta': 'two'}
    r = client.post('/post',
                    data=_json.dumps(payload),
                    content_type='application/json')
    assert r.status_code == 200
    body = r.get_json()
    assert body['json'] == {'alpha': 1, 'beta': 'two'}
    assert body['form'] == {}
    assert body['args'] == {}
    assert body['files'] == {}
    assert 'url' in body
    assert 'headers' in body
    assert 'origin' in body

test_post_json_body_reflected_in_json_field()

from httpbin.core import app
client = app.test_client()

def test_post_empty_body_boundary():
    r = client.post('/post', data=b'', content_type='application/octet-stream')
    assert r.status_code == 200
    body = r.get_json()
    required_keys = {'url', 'args', 'headers', 'form', 'data', 'files', 'json', 'origin'}
    assert set(body.keys()) == required_keys
    assert body['data'] == ''
    assert body['form'] == {}
    assert body['json'] is None
    assert body['files'] == {}
    assert body['args'] == {}
    assert isinstance(body['url'], str)
    assert len(body['url']) > 0

test_post_empty_body_boundary()
